		CreateImpliedMatchesTask myTask = new CreateImpliedMatchesTask(controller, matches);
		myTask.addTaskListener(new _Anon_TaskListener_1());
		controller.runVTTask(myTask);
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		List<VTImpliedMatchInfo> matches = provider.getSelectedImpliedMatches();
		return matches.size() > 0;
	}

